#pragma region Parameterized Test Setup & Runner

struct EndToEndTestCase {
  std::string name;
  std::string source;
  std::vector<int> expected_compile_codes = {0};
  std::string expected_out = "";
  std::string stdin_input = "";
  std::vector<int> expected_runtime_codes = {0};
};

inline std::string FormatCodeList(const std::vector<int> &codes) {
  std::string s = "{";
  for (size_t i = 0; i < codes.size(); ++i) {
    if (i > 0) {
      s += ", ";
    }
    s += std::to_string(codes[i]);
  }
  s += "}";
  return s;
}

inline void PrintTo(const EndToEndTestCase &tc, std::ostream *os) {
  *os << "{ name: \"" << tc.name << "\""
      << ", expected_compile_codes: "
      << FormatCodeList(tc.expected_compile_codes)
      << ", expected_runtime_codes: "
      << FormatCodeList(tc.expected_runtime_codes)
      << ", stdin_input: " << ::testing::PrintToString(tc.stdin_input)
      << ", expected_out: " << ::testing::PrintToString(tc.expected_out)
      << " }";
}

inline EndToEndTestCase E2EOk(std::string name, std::string source,
                              std::string expected_out = "",
                              std::string stdin_input = "") {
  return EndToEndTestCase{
      std::move(name),         std::move(source),      {0},
      std::move(expected_out), std::move(stdin_input), {0},
  };
}

inline EndToEndTestCase E2ECompileErr(std::string name, std::string source,
                                      std::initializer_list<int> codes) {
  return EndToEndTestCase{
      std::move(name), std::move(source), std::vector<int>(codes), "", "", {0},
  };
}

inline EndToEndTestCase E2ERuntimeErr(std::string name, std::string source,
                                      std::initializer_list<int> runtime_codes,
                                      std::string stdin_input = "") {
  return EndToEndTestCase{
      std::move(name),
      std::move(source),
      {0},
      "",
      std::move(stdin_input),
      std::vector<int>(runtime_codes),
  };
}

struct RunResult {
  std::string stdout_str;
  int exit_code = -1;
};

class EndToEndParamTest : public ::testing::TestWithParam<EndToEndTestCase> {
protected:
  std::filesystem::path src_file_;
  std::filesystem::path code_file_;
  std::filesystem::path in_file_;

  std::filesystem::path temp_file_path(const std::string &ext) const {
    const ::testing::TestInfo *info =
        ::testing::UnitTest::GetInstance()->current_test_info();

    std::string suite_name =
        (info != nullptr) ? info->test_suite_name() : "unknown_suite";
    for (char &c : suite_name) {
      if (c == '/') {
        c = '_';
      }
    }

    return std::filesystem::path(testing::TempDir()) /
           (suite_name + "_" + GetParam().name + ext);
  }

  static bool contains_code(const std::vector<int> &allowed, int actual) {
    return std::find(allowed.begin(), allowed.end(), actual) != allowed.end();
  }

  RunResult run_ic26int(inner_statement_t *generated_code,
                        const std::string &stdin_input) {
    code_file_ = temp_file_path(".ifjcode");
    FILE *out = std::fopen(code_file_.string().c_str(), "wb");
    if (!out) {
      ADD_FAILURE() << "Failed to open temp code file: " << code_file_;
      return {};
    }
    codegen_print_program(generated_code, out);
    std::fclose(out);

    std::string stdin_redirect = "/dev/null";
    if (!stdin_input.empty()) {
      in_file_ = temp_file_path(".in");
      std::ofstream in(in_file_, std::ios::binary);
      if (!in) {
        ADD_FAILURE() << "Failed to open temp stdin file: " << in_file_;
        return {};
      }
      in << stdin_input;
      stdin_redirect = "\"" + in_file_.string() + "\"";
    }

    std::string cmd =
        "./ic26int \"" + code_file_.string() + "\" < " + stdin_redirect;
    FILE *pipe = popen(cmd.c_str(), "r");
    if (!pipe) {
      ADD_FAILURE() << "popen() failed for command: " << cmd;
      return {};
    }

    RunResult res;
    char buffer[4096];
    size_t bytes_read = 0;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), pipe)) > 0) {
      res.stdout_str.append(buffer, bytes_read);
    }

    int raw_status = pclose(pipe);
    res.exit_code = WIFEXITED(raw_status) ? WEXITSTATUS(raw_status) : -1;
    return res;
  }

  void TearDown() override {
    if (HasFailure()) {
      if (!src_file_.empty() && std::filesystem::exists(src_file_)) {
        std::cout << "[  INFO    ] Source input preserved at:   " << src_file_
                  << '\n';
      }
      if (!code_file_.empty() && std::filesystem::exists(code_file_)) {
        std::cout << "[  INFO    ] Generated code preserved at: " << code_file_
                  << '\n';
      }
      if (!in_file_.empty() && std::filesystem::exists(in_file_)) {
        std::cout << "[  INFO    ] Stdin input preserved at:    " << in_file_
                  << '\n';
      }
      return;
    }

    if (!src_file_.empty()) {
      std::filesystem::remove(src_file_);
    }
    if (!code_file_.empty()) {
      std::filesystem::remove(code_file_);
    }
    if (!in_file_.empty()) {
      std::filesystem::remove(in_file_);
    }
  }
};

TEST_P(EndToEndParamTest, CompilesAndExecutes) {
  const auto &param = GetParam();

  src_file_ = temp_file_path(".scala");
  {
    std::ofstream src_out(src_file_, std::ios::binary);
    ASSERT_TRUE(src_out.is_open()) << "Failed to create " << src_file_;
    src_out << param.source;
  }

  FILE *src_fp = std::fopen(src_file_.string().c_str(), "rb");
  ASSERT_NE(src_fp, nullptr) << "Failed to open " << src_file_;

  ast_node_t *root = nullptr;
  hashtable_t *symtable = nullptr;
  inner_statement_t *generated_code = nullptr;

  struct PipelineCleanup {
    FILE **fp;
    ast_node_t **root;
    hashtable_t **symtable;
    inner_statement_t **code;

    ~PipelineCleanup() {
      if (fp != nullptr && *fp != nullptr) {
        std::fclose(*fp);
      }
      if (code != nullptr && *code != nullptr) {
        destroy_statement_list(*code);
      }
      if (symtable != nullptr && *symtable != nullptr) {
        ht_destruct(symtable);
      }
      if (root != nullptr && *root != nullptr) {
        destroy_node(*root);
      }
    }
  } cleanup{&src_fp, &root, &symtable, &generated_code};

  // Phase 1: Lexical + Syntax Analysis
  err_code_t err = parse(&root, src_fp);
  std::fclose(src_fp);
  src_fp = nullptr;

  if (err != NO_ERR) {
    EXPECT_TRUE(contains_code(param.expected_compile_codes, err))
        << "Parse failed with code " << err << ", expected one of "
        << FormatCodeList(param.expected_compile_codes);
    return;
  }

  ASSERT_NE(root, nullptr);

  // Phase 2: Semantic Analysis
  symtable = create_builtin_symtable();
  ASSERT_NE(symtable, nullptr);

  ast_node_t *main_node = nullptr;
  err = analyse(root, symtable, &main_node);
  if (err != NO_ERR) {
    EXPECT_TRUE(contains_code(param.expected_compile_codes, err))
        << "Semantic analysis failed with code " << err << ", expected one of "
        << FormatCodeList(param.expected_compile_codes);
    return;
  }

  ASSERT_NE(main_node, nullptr);

  // Phase 3: AST -> IFJcode26 Conversion
  err = ast_convert(main_node, &generated_code);
  if (err != NO_ERR) {
    EXPECT_TRUE(contains_code(param.expected_compile_codes, err))
        << "ast_convert failed with code " << err << ", expected one of "
        << FormatCodeList(param.expected_compile_codes);
    return;
  }

  ASSERT_TRUE(contains_code(param.expected_compile_codes, 0))
      << "Compiler succeeded (0), but expected compile error in "
      << FormatCodeList(param.expected_compile_codes);

  // Phase 4: Execution via ic26int
  ASSERT_TRUE(std::filesystem::exists("./ic26int"))
      << "./ic26int not found in PWD";

  RunResult actual = run_ic26int(generated_code, param.stdin_input);
  EXPECT_TRUE(contains_code(param.expected_runtime_codes, actual.exit_code))
      << "Interpreter exited with code " << actual.exit_code
      << ", expected one of " << FormatCodeList(param.expected_runtime_codes);

  if (actual.exit_code == 0 && contains_code(param.expected_runtime_codes, 0)) {
    EXPECT_EQ(actual.stdout_str, param.expected_out);
  }
}

