#pragma region Test Registration

std::vector<EndToEndTestCase> CollectAllEndToEndTests() {
  std::vector<EndToEndTestCase> all;
  auto append = [&all](std::vector<EndToEndTestCase> &&chunk) {
    all.insert(all.end(), std::make_move_iterator(chunk.begin()),
               std::make_move_iterator(chunk.end()));
  };

  append(MakeLexErrorTests());
  append(MakeSynErrorTests());
  append(MakeSemDefErrorTests());
  append(MakeSemTypeErrorTests());
  append(MakeSemOtherErrorTests());
  append(MakeRuntimeErrorTests());
  append(MakeBaseSuccessTests());
  append(MakeExtFunexpTests());
  append(MakeExtBoolthenTests());
  append(MakeExtControlTests());
  append(MakeExtValmemTests());
  append(MakeExtAlgebdtTests());
  append(MakeExtInterpolatedsTests());
  append(MakeExtLambdasTests());
  append(MakeExtListsTests());
  append(MakeExtExtkwTests());
  append(MakeExtParamlistsTests());
  append(MakeExtMixTests());

  return all;
}

INSTANTIATE_TEST_SUITE_P(
    ScalaEndToEndTest, EndToEndParamTest,
    ::testing::ValuesIn(CollectAllEndToEndTests()),
    [](const ::testing::TestParamInfo<EndToEndTestCase> &info) {
      return info.param.name;
    });

